using System;using System.Collections.Generic;using System.Linq;using System.Globalization;using Avalonia;using Avalonia.Controls;using Avalonia.Interactivity;using Avalonia.Layout;using Avalonia.Media;using Kreta.Core;using Kreta.Contexts;public class HelyettesitesSzervezoView : IEvolView{    private IDirectorContext? _context;    private DatePicker? _datePicker;    private ListBox? _absencesListBox;    private Button? _newAbsenceButton;    private StackPanel? _absenceEditPanel;    private ComboBox? _absentTeacherComboBox;    private TextBox? _reasonTextBox;    private Button? _saveAbsenceButton;    private StackPanel? _substitutionPanel;    private TextBlock? _substitutionHeader;    private ListBox? _lessonsListBox;    private ComboBox? _substituteTeacherComboBox;    private Button? _saveSubstitutionButton;    private TextBlock? _statusTextBlock;    private List<GenericRecord>? _allAbsences;    private List<GenericRecord>? _allLessons;    private List<GenericRecord>? _allSubstitutions;    private List<User>? _allTeachers;    private GenericRecord? _selectedAbsence;    private GenericRecord? _selectedLesson;    private const string AbsenceEntityType = "TeacherAbsence";    private const string LessonEntityType = "Lesson";    private const string SubstitutionEntityType = "Substitution";    public new string Name => "Helyettesítés Szervező";    public string Description => "Tanári hiányzások rögzítése és a helyettesítések megszervezése.";    public HelyettesitesSzervezoView() { }    public HelyettesitesSzervezoView(IDirectorContext context)    {        _context = context;    }    public Control CreateView()    {        _datePicker = new DatePicker        {            SelectedDate = DateTime.Today        };        _datePicker.SelectedDateChanged += DatePicker_SelectedDateChanged;        _absencesListBox = new ListBox();        _absencesListBox.SelectionChanged += AbsencesListBox_SelectionChanged;        _newAbsenceButton = new Button { Content = "Új hiányzás rögzítése" };        _newAbsenceButton.Click += NewAbsenceButton_Click;        _absenceEditPanel = new StackPanel { Spacing = 5, IsVisible = false };        _substituteTeacherComboBox = new ComboBox { PlaceholderText = "Helyettesítő tanár..." };        _substitutionPanel = new StackPanel { Spacing = 5, Margin = new Thickness(10, 0, 0, 0), IsVisible = false };        _statusTextBlock = new TextBlock { Margin = new Thickness(0, 10, 0, 0) };        var mainGrid = new Grid        {            ColumnDefinitions = new ColumnDefinitions("*,*"),            RowDefinitions = new RowDefinitions("Auto,*")        };        var leftPanel = new StackPanel { Spacing = 10 };        leftPanel.Children.Add(new TextBlock { Text = "Dátum választása:", FontWeight = FontWeight.Bold });        leftPanel.Children.Add(_datePicker);        leftPanel.Children.Add(new TextBlock { Text = "Hiányzó tanárok:", FontWeight = FontWeight.Bold, Margin = new Thickness(0, 10, 0, 0) });        leftPanel.Children.Add(_absencesListBox);        leftPanel.Children.Add(_newAbsenceButton);        leftPanel.Children.Add(CreateAbsenceEditPanel());        Grid.SetColumn(leftPanel, 0);        Grid.SetRow(leftPanel, 0);        Grid.SetRowSpan(leftPanel, 2);        var rightPanel = new StackPanel { Spacing = 10 };        rightPanel.Children.Add(CreateSubstitutionPanel());        Grid.SetColumn(rightPanel, 1);        Grid.SetRow(rightPanel, 0);        Grid.SetRowSpan(rightPanel, 2);        mainGrid.Children.Add(leftPanel);        mainGrid.Children.Add(rightPanel);        var viewContainer = new StackPanel        {            Orientation = Orientation.Vertical,            Spacing = 10,            Margin = new Thickness(15)        };        viewContainer.Children.Add(mainGrid);        viewContainer.Children.Add(_statusTextBlock);        LoadInitialData();        return viewContainer;    }    private Control CreateAbsenceEditPanel()    {        _absentTeacherComboBox = new ComboBox { PlaceholderText = "Hiányzó tanár..." };        _reasonTextBox = new TextBox { PlaceholderText = "Hiányzás oka" };        _saveAbsenceButton = new Button { Content = "Hiányzás mentése" };        _saveAbsenceButton.Click += SaveAbsenceButton_Click;        _absenceEditPanel.Children.Add(_absentTeacherComboBox);        _absenceEditPanel.Children.Add(_reasonTextBox);        _absenceEditPanel.Children.Add(_saveAbsenceButton);        return _absenceEditPanel;    }    private Control CreateSubstitutionPanel()    {        _substitutionHeader = new TextBlock { FontWeight = FontWeight.Bold };        _lessonsListBox = new ListBox();        _lessonsListBox.SelectionChanged += LessonsListBox_SelectionChanged;        _saveSubstitutionButton = new Button { Content = "Helyettesítés mentése", IsEnabled = false };        _saveSubstitutionButton.Click += SaveSubstitutionButton_Click;        _substitutionPanel.Children.Add(_substitutionHeader);        _substitutionPanel.Children.Add(_lessonsListBox);        _substitutionPanel.Children.Add(_substituteTeacherComboBox);        _substitutionPanel.Children.Add(_saveSubstitutionButton);        return _substitutionPanel;    }    private void LoadInitialData()    {        if (_context == null) return;        _allTeachers = _context.GetAllUsers().Where(u => u.Role == Role.Teacher).ToList();        if (_absentTeacherComboBox != null)            _absentTeacherComboBox.ItemsSource = _allTeachers.Select(t => t.Name).ToList();        if (_substituteTeacherComboBox != null)            _substituteTeacherComboBox.ItemsSource = _allTeachers.Select(t => t.Name).ToList();        _allLessons = _context.QueryEntities(LessonEntityType);        _allSubstitutions = _context.QueryEntities(SubstitutionEntityType);        LoadAbsencesForSelectedDate();    }    private void DatePicker_SelectedDateChanged(object? sender, DatePickerSelectedValueChangedEventArgs e)    {        LoadAbsencesForSelectedDate();        if (_substitutionPanel != null) _substitutionPanel.IsVisible = false;        if (_absenceEditPanel != null) _absenceEditPanel.IsVisible = false;    }    private void LoadAbsencesForSelectedDate()    {        if (_context == null || _datePicker?.SelectedDate == null || _absencesListBox == null) return;        var selectedDate = _datePicker.SelectedDate.Value.ToString("yyyy-MM-dd");        _allAbsences = _context.QueryEntities(AbsenceEntityType);        var todaysAbsences = _allAbsences.Where(a => a.Data.ContainsKey("Date") && a.Data["Date"] == selectedDate).ToList();        var teacherNames = _allTeachers?.ToDictionary(t => t.Id.ToString(), t => t.Name) ?? new Dictionary<string, string>();        _absencesListBox.ItemsSource = todaysAbsences.Select(a =>        {            string teacherName = "Ismeretlen tanár";            if (a.Data.ContainsKey("TeacherId") && teacherNames.ContainsKey(a.Data["TeacherId"]))            {                teacherName = teacherNames[a.Data["TeacherId"]];            }            return $"{teacherName} - Ok: {a.Data.GetValueOrDefault("Reason", "Nincs megadva")}";        }).ToList();        _absencesListBox.Tag = todaysAbsences;    }    private void NewAbsenceButton_Click(object? sender, RoutedEventArgs e)    {        if (_absenceEditPanel == null) return;        _selectedAbsence = null;        _absenceEditPanel.IsVisible = true;        if (_absentTeacherComboBox != null) _absentTeacherComboBox.SelectedIndex = -1;        if (_reasonTextBox != null) _reasonTextBox.Text = string.Empty;    }    private void SaveAbsenceButton_Click(object? sender, RoutedEventArgs e)    {        if (_context == null || _absentTeacherComboBox?.SelectedItem == null || _datePicker?.SelectedDate == null)        {            SetStatus("Hiba: Nincs minden adat kitöltve!", true);            return;        }        var selectedTeacher = _allTeachers?.FirstOrDefault(t => t.Name == _absentTeacherComboBox.SelectedItem.ToString());        if (selectedTeacher == null) return;        var data = new Dictionary<string, string>        {            { "TeacherId", selectedTeacher.Id.ToString() },            { "Date", _datePicker.SelectedDate.Value.ToString("yyyy-MM-dd") },            { "Reason", _reasonTextBox?.Text ?? string.Empty }        };        var resultId = _context.SaveEntity(AbsenceEntityType, data, _selectedAbsence?.Id);        SetStatus(resultId > 0 ? "Hiányzás sikeresen mentve." : "Hiba történt a mentés során.", resultId <= 0);        if (resultId > 0)        {            LoadAbsencesForSelectedDate();            if (_absenceEditPanel != null) _absenceEditPanel.IsVisible = false;        }    }    private void AbsencesListBox_SelectionChanged(object? sender, SelectionChangedEventArgs e)    {        if (_absencesListBox?.SelectedItem == null || _substitutionPanel == null)        {            if (_substitutionPanel != null) _substitutionPanel.IsVisible = false;            return;        }        var absences = _absencesListBox.Tag as List<GenericRecord>;        _selectedAbsence = absences?[_absencesListBox.SelectedIndex];        if (_selectedAbsence == null || !_selectedAbsence.Data.ContainsKey("TeacherId")) return;        var absentTeacherId = int.Parse(_selectedAbsence.Data["TeacherId"]);        var absentTeacher = _allTeachers?.FirstOrDefault(t => t.Id == absentTeacherId);        if (absentTeacher == null) return;        _substitutionPanel.IsVisible = true;        if (_substitutionHeader != null) _substitutionHeader.Text = $"{absentTeacher.Name} helyettesítendő órái:";        LoadLessonsForTeacher(absentTeacher.Name);    }    private void LoadLessonsForTeacher(string teacherName)    {        if (_datePicker?.SelectedDate == null || _lessonsListBox == null) return;        var selectedDate = _datePicker.SelectedDate.Value;        var dayOfWeek = selectedDate.DayOfWeek.ToString();        var lessonsForDay = _allLessons?            .Where(l => l.Data.ContainsKey("Teacher") && l.Data["Teacher"] == teacherName &&                       l.Data.ContainsKey("DayOfWeek") && l.Data["DayOfWeek"] == dayOfWeek)            .OrderBy(l => l.Data.GetValueOrDefault("LessonNumber", "0"))            .ToList();        var existingSubstitutions = _allSubstitutions            .Where(s => s.Data.ContainsKey("Date") && s.Data["Date"] == selectedDate.ToString("yyyy-MM-dd"))            .ToDictionary(s => s.Data["LessonId"]);        _lessonsListBox.ItemsSource = lessonsForDay?.Select(l =>        {            string substitutionInfo = "";            if (existingSubstitutions.ContainsKey(l.Id.ToString()))            {                var sub = existingSubstitutions[l.Id.ToString()];                var subTeacherId = int.Parse(sub.Data["SubstituteTeacherId"]);                var subTeacher = _allTeachers?.FirstOrDefault(t => t.Id == subTeacherId);                substitutionInfo = $" (Helyettes: {subTeacher?.Name ?? "Ismeretlen"})";            }            return $"Óra: {l.Data["LessonNumber"]}. - {l.Data["Subject"]} ({l.Data["ClassName"]}) - Terem: {l.Data["Room"]}{substitutionInfo}";        }).ToList();        _lessonsListBox.Tag = lessonsForDay;    }    private void LessonsListBox_SelectionChanged(object? sender, SelectionChangedEventArgs e)    {        if (_saveSubstitutionButton != null)            _saveSubstitutionButton.IsEnabled = _lessonsListBox?.SelectedItem != null;    }    private void SaveSubstitutionButton_Click(object? sender, RoutedEventArgs e)    {        if (_context == null || _lessonsListBox?.SelectedItem == null || _substituteTeacherComboBox?.SelectedItem == null || _datePicker?.SelectedDate == null)        {            SetStatus("Hiba: Válassz ki órát és helyettesítő tanárt!", true);            return;        }        var lessons = _lessonsListBox.Tag as List<GenericRecord>;        _selectedLesson = lessons?[_lessonsListBox.SelectedIndex];        var substituteTeacher = _allTeachers?.FirstOrDefault(t => t.Name == _substituteTeacherComboBox.SelectedItem.ToString());        if (_selectedLesson == null || substituteTeacher == null) return;                var existing = _allSubstitutions?.FirstOrDefault(s => s.Data["LessonId"] == _selectedLesson.Id.ToString() && s.Data["Date"] == _datePicker.SelectedDate.Value.ToString("yyyy-MM-dd"));        var data = new Dictionary<string, string>        {            { "LessonId", _selectedLesson.Id.ToString() },            { "OriginalTeacherId", _selectedAbsence?.Data["TeacherId"] ?? "0" },            { "SubstituteTeacherId", substituteTeacher.Id.ToString() },            { "Date", _datePicker.SelectedDate.Value.ToString("yyyy-MM-dd") },            { "Status", "Scheduled" }        };        var resultId = _context.SaveEntity(SubstitutionEntityType, data, existing?.Id);        SetStatus(resultId > 0 ? "Helyettesítés mentve." : "Hiba a mentés során.", resultId <= 0);        if (resultId > 0)        {            _allSubstitutions = _context.QueryEntities(SubstitutionEntityType);            LoadLessonsForTeacher(_allTeachers.First(t => t.Id.ToString() == _selectedAbsence.Data["TeacherId"]).Name);        }    }    private void SetStatus(string message, bool isError = false)    {        if (_statusTextBlock == null) return;        _statusTextBlock.Text = message;        _statusTextBlock.Foreground = isError ? Brushes.Red : Brushes.Green;    }}